-- ============================================================
-- NagrikSaarathi — Reference SQL Schema
-- ============================================================
-- This file is a READ-ONLY reference generated from the
-- canonical SQLAlchemy models in backend/app/models.py.
-- Do NOT edit this file directly to change the schema;
-- modify the ORM models and create an Alembic migration instead.
-- ============================================================

CREATE TABLE languages (
    id                          INTEGER      PRIMARY KEY AUTOINCREMENT,
    language_code               VARCHAR(10)  NOT NULL UNIQUE,
    english_name                VARCHAR(60)  NOT NULL,
    native_name                 VARCHAR(100) NOT NULL,
    writing_system              VARCHAR(40)  NOT NULL,
    direction                   VARCHAR(3)   NOT NULL DEFAULT 'ltr'
                                CHECK (direction IN ('ltr', 'rtl')),
    enabled                     BOOLEAN      NOT NULL DEFAULT 1,
    supports_text               BOOLEAN      NOT NULL DEFAULT 1,
    supports_speech_recognition BOOLEAN      NOT NULL DEFAULT 0,
    supports_text_to_speech     BOOLEAN      NOT NULL DEFAULT 0
);

CREATE TABLE government_schemes (
    id                                  INTEGER      PRIMARY KEY AUTOINCREMENT,
    slug                                VARCHAR(120) NOT NULL UNIQUE,
    display_name                        VARCHAR(200) NOT NULL,
    description                         TEXT         NOT NULL DEFAULT '',
    department_name                     VARCHAR(200) NOT NULL DEFAULT '',
    official_source_url                 VARCHAR(500) NOT NULL DEFAULT '',
    source_document_reference           VARCHAR(500),
    is_demo                             BOOLEAN      NOT NULL DEFAULT 0,
    is_active                           BOOLEAN      NOT NULL DEFAULT 1,
    official_application_url            VARCHAR(500),
    last_verified_at                    TIMESTAMP WITH TIME ZONE,
    verification_status                 VARCHAR(20)  NOT NULL DEFAULT 'verified'
                                        CHECK (verification_status IN ('verified', 'pending_review', 'outdated')),
    verification_source_reference       VARCHAR(500),
    descriptions_by_language            JSON         NOT NULL,
    application_instructions_by_language JSON        NOT NULL,
    created_at                          TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at                          TIMESTAMP WITH TIME ZONE NOT NULL
);

CREATE TABLE form_fields (
    id                                  INTEGER      PRIMARY KEY AUTOINCREMENT,
    scheme_id                           INTEGER      NOT NULL
                                        REFERENCES government_schemes(id) ON DELETE CASCADE,
    field_key                           VARCHAR(120) NOT NULL,
    field_type                          VARCHAR(40)  NOT NULL DEFAULT 'text',
    required                            BOOLEAN      NOT NULL DEFAULT 1,
    sort_order                          INTEGER      NOT NULL DEFAULT 0,
    labels_by_language                  JSON         NOT NULL,
    explanations_by_language            JSON         NOT NULL,
    instructions_by_language            JSON         NOT NULL,
    examples_by_language                JSON         NOT NULL,
    validation_guidance_by_language     JSON         NOT NULL,
    validation_rules                    JSON         NOT NULL,
    source_reference                    VARCHAR(500),
    verification_status                 VARCHAR(20)  NOT NULL DEFAULT 'verified'
                                        CHECK (verification_status IN ('verified', 'pending_review', 'outdated')),
    last_verified_at                    TIMESTAMP WITH TIME ZONE,
    UNIQUE (scheme_id, field_key)
);

CREATE TABLE scheme_eligibility_requirements (
    id                                  INTEGER      PRIMARY KEY AUTOINCREMENT,
    scheme_id                           INTEGER      NOT NULL
                                        REFERENCES government_schemes(id) ON DELETE CASCADE,
    criterion_key                       VARCHAR(100) NOT NULL,
    criterion_type                      VARCHAR(40)  NOT NULL DEFAULT 'other'
                                        CHECK (criterion_type IN (
                                            'age', 'annual_income', 'academic_qualification',
                                            'domicile_residency', 'social_category', 'gender',
                                            'institutional_enrollment', 'other'
                                        )),
    operator                            VARCHAR(20),
    threshold_value                     JSON,
    is_mandatory                        BOOLEAN      NOT NULL DEFAULT 1,
    sort_order                          INTEGER      NOT NULL DEFAULT 0,
    titles_by_language                  JSON         NOT NULL,
    descriptions_by_language            JSON         NOT NULL,
    official_source_reference           VARCHAR(500),
    verification_status                 VARCHAR(20)  NOT NULL DEFAULT 'verified'
                                        CHECK (verification_status IN ('verified', 'pending_review', 'outdated')),
    last_verified_at                    TIMESTAMP WITH TIME ZONE,
    UNIQUE (scheme_id, criterion_key)
);

CREATE TABLE scheme_document_requirements (
    id                                  INTEGER      PRIMARY KEY AUTOINCREMENT,
    scheme_id                           INTEGER      NOT NULL
                                        REFERENCES government_schemes(id) ON DELETE CASCADE,
    document_code                       VARCHAR(100) NOT NULL,
    requirement_type                    VARCHAR(30)  NOT NULL DEFAULT 'always_required'
                                        CHECK (requirement_type IN ('always_required', 'conditional', 'optional')),
    condition_rule                      JSON,
    is_mandatory                        BOOLEAN      NOT NULL DEFAULT 1,
    sort_order                          INTEGER      NOT NULL DEFAULT 0,
    titles_by_language                  JSON         NOT NULL,
    descriptions_by_language            JSON         NOT NULL,
    issuing_authority                   VARCHAR(250),
    validity_period_info                VARCHAR(250),
    official_source_url                 VARCHAR(500),
    source_reference                    VARCHAR(500),
    verification_status                 VARCHAR(20)  NOT NULL DEFAULT 'verified'
                                        CHECK (verification_status IN ('verified', 'pending_review', 'outdated')),
    last_verified_at                    TIMESTAMP WITH TIME ZONE,
    UNIQUE (scheme_id, document_code)
);

CREATE TABLE scheme_application_steps (
    id                                  INTEGER      PRIMARY KEY AUTOINCREMENT,
    scheme_id                           INTEGER      NOT NULL
                                        REFERENCES government_schemes(id) ON DELETE CASCADE,
    step_number                         INTEGER      NOT NULL,
    step_key                            VARCHAR(100) NOT NULL,
    titles_by_language                  JSON         NOT NULL,
    instructions_by_language            JSON         NOT NULL,
    official_action_url                 VARCHAR(500),
    source_reference                    VARCHAR(500),
    verification_status                 VARCHAR(20)  NOT NULL DEFAULT 'verified'
                                        CHECK (verification_status IN ('verified', 'pending_review', 'outdated')),
    last_verified_at                    TIMESTAMP WITH TIME ZONE,
    UNIQUE (scheme_id, step_number)
);

CREATE TABLE assisted_sessions (
    id                 VARCHAR(36) PRIMARY KEY,
    scheme_id          INTEGER     NOT NULL
                       REFERENCES government_schemes(id) ON DELETE CASCADE,
    selected_language  VARCHAR(10) NOT NULL,
    channel            VARCHAR(20) NOT NULL DEFAULT 'web'
                       CHECK (channel IN ('web', 'assisted_desk')),
    status             VARCHAR(20) NOT NULL DEFAULT 'in_progress'
                       CHECK (status IN ('in_progress', 'completed',
                                         'abandoned', 'needs_human_help')),
    analytics_consent  BOOLEAN     NOT NULL DEFAULT 0,
    is_demo            BOOLEAN     NOT NULL DEFAULT 0,
    started_at         TIMESTAMP WITH TIME ZONE NOT NULL,
    ended_at           TIMESTAMP WITH TIME ZONE
);
-- PRIVACY: This table intentionally contains NO columns for
-- citizen PII, form answers, or uploaded documents.

CREATE TABLE session_events (
    id                 INTEGER     PRIMARY KEY AUTOINCREMENT,
    session_id         VARCHAR(36) NOT NULL
                       REFERENCES assisted_sessions(id) ON DELETE CASCADE,
    field_key          VARCHAR(120),
    event_type         VARCHAR(40) NOT NULL
                       CHECK (event_type IN (
                           'help_requested', 'voice_used',
                           'validation_failed', 'field_completed',
                           'issue_resolved', 'issue_unresolved',
                           'application_completed', 'abandoned',
                           'human_help_requested'
                       )),
    barrier_category   VARCHAR(40)
                       CHECK (barrier_category IS NULL OR barrier_category IN (
                           'confusing_question', 'missing_document',
                           'language_difficulty', 'validation_error',
                           'technical_failure', 'other'
                       )),
    resolution_status  VARCHAR(20)
                       CHECK (resolution_status IS NULL OR resolution_status IN (
                           'resolved', 'unresolved', 'escalated'
                       )),
    language_code      VARCHAR(10),
    created_at         TIMESTAMP WITH TIME ZONE NOT NULL
);
-- PRIVACY: This table records structured event types only.
-- It NEVER stores actual values entered by citizens.

CREATE TABLE translation_reviews (
    id                 INTEGER      PRIMARY KEY AUTOINCREMENT,
    resource_type      VARCHAR(60)  NOT NULL,
    resource_key       VARCHAR(200) NOT NULL,
    language_code      VARCHAR(10)  NOT NULL,
    translation_status VARCHAR(20)  NOT NULL DEFAULT 'draft'
                       CHECK (translation_status IN ('draft', 'reviewed', 'approved')),
    reviewer_note      TEXT,
    updated_at         TIMESTAMP WITH TIME ZONE NOT NULL,
    UNIQUE (resource_type, resource_key, language_code)
);

CREATE TABLE users (
    id                 INTEGER      PRIMARY KEY AUTOINCREMENT,
    identifier         VARCHAR(120) NOT NULL UNIQUE,
    email              VARCHAR(120),
    mobile             VARCHAR(20),
    hashed_password    VARCHAR(255) NOT NULL,
    role               VARCHAR(20)  NOT NULL DEFAULT 'citizen'
                       CHECK (role IN ('citizen', 'official')),
    full_name          VARCHAR(120),
    department         VARCHAR(150),
    is_active          BOOLEAN      NOT NULL DEFAULT 1,
    is_demo            BOOLEAN      NOT NULL DEFAULT 0,
    created_at         TIMESTAMP WITH TIME ZONE NOT NULL,
    last_login_at      TIMESTAMP WITH TIME ZONE
);
